 469→  /** Manually refresh the room list and update the atom */
 470→  public static refreshRoomList = async () => {
 471→    if (!this.instance) return;
 472→
 473→    try {
 474→      const roomsArray = this.getRooms();
 475→
 476→      const sortedRooms = await Promise.all(
 477→        roomsArray.map(async (room) => ({
 478→          room,
 479→          timestamp: (await room.latestEvent())?.timestamp || 0,
 480→        })),
 481→      );
 482→
 483→      const filteredAndSortedRooms = sortedRooms
 484→        .filter(({ room }) => {
 485→          const membership = room.membership();
 486→
 487→          return (
 488→            membership !== Membership.Banned &&
 489→            membership !== Membership.Left &&
 490→            membership !== Membership.Knocked
 491→          );
 492→        })
 493→        .sort((a, b) => {
 494→          const aInvited = a.room.membership() === Membership.Invited ? 1 : 0;
 495→          const bInvited = b.room.membership() === Membership.Invited ? 1 : 0;
 496→          if (aInvited !== bInvited) return bInvited - aInvited;
 497→
 498→          return Number(b.timestamp) - Number(a.timestamp);
 499→        });
 500→
 501→      MatrixJotaiStore.set(
 502→        MatrixAtoms.roomList,
 503→        filteredAndSortedRooms.map(({ room }) => room),
 504→      );
 505→    } catch (error) {
 506→      console.error("Failed to refresh room list:", error);
 507→    }
 508→  };
