 585→  public static sendMessage = async (roomId: string, message: string) => {
 586→    if (!this.instance) throw new Error("Client not initialized");
 587→    const room = this.instance.getRoom(roomId);
 588→    if (!room) throw new Error("Room not found");
 589→    const timeline = await room.timeline();
 590→    if (!timeline) throw new Error("Timeline not found");
 591→
 592→    // Create message content from markdown (supports plain text too)
 593→    const messageContent = messageEventContentFromMarkdown(message);
 594→
 595→    // Send the message and return the send handle
 596→    await timeline.send(messageContent);
 597→  };
