1090→  public static getReadReceipts = async (event: EventTimelineItem) => {
1091→    const userIds = Array.from(event.readReceipts.keys()).map(
1092→      (userIds) => userIds,
1093→    );
1094→
1095→    // Don't show read receipts for the sender's own message
1096→    const filteredUserIds = userIds.filter((userId) => userId !== event.sender);
1097→
1098→    if (!filteredUserIds.length) {
1099→      return [];
1100→    }
1101→
1102→    try {
1103→      const profilePromises = filteredUserIds.map((userId) =>
1104→        this.instance?.getProfile(userId),
1105→      );
1106→      const profiles = await Promise.allSettled(profilePromises);
1107→      return profiles
1108→        .filter((p) => p.status === "fulfilled")
1109→        .map((p) => p.value)
1110→        .filter((p) => p !== undefined);
1111→    } catch (error) {
1112→      console.error("Failed to get read receipt users:", error);
1113→      return [];
1114→    }
1115→  };
