1879→    roomId: string,
1880→    eventId: string,
1881→  ): Promise<void> => {
1882→    if (!this.instance) throw new Error("Client not initialized");
1883→
1884→    const room = this.instance.getRoom(roomId);
1885→    if (!room) throw new Error("Room not found");
1886→
1887→    const timeline = await room.timeline();
1888→    if (!timeline) throw new Error("Timeline not found");
1889→
1890→    await timeline.unpinEvent(eventId);
1891→  };
1892→
1893→  /** Check if a message is pinned */
1894→  public static isMessagePinned = async (
1895→    roomId: string,
1896→    eventId: string,
1897→  ): Promise<boolean> => {
1898→    const pinnedEvents = await this.getPinnedEventIds(roomId);
1899→    return pinnedEvents.includes(eventId);
1900→  };
1901→}
