 28→  const title = () => {
 29→    if (recoveryKey) return "Recovery key";
 30→    if (recoveryState === RecoveryState.Enabled) return "Change recovery key";
 31→    if (recoveryState === RecoveryState.Disabled) {
 32→      return "Set up a recovery key";
 33→    }
 34→    if (recoveryState === RecoveryState.Incomplete) {
 35→      return "Enter existing recovery key and validate your device.";
 36→    }
 37→    return "Set up a recovery key";
