148→            </Text>
149→          </Block>
150→        ) : (
151→          <Block>
152→            {isGeneratingRecoveryKey ? (
153→              <Block>
154→                <Loading
155→                  text="Generating recovery key..."
156→                  isFullScreen={false}
157→                />
158→              </Block>
