  1→import { Block, Text } from "@prototyp/skeletor";
  2→import type { NativeStackScreenProps } from "@react-navigation/native-stack";
  3→import { useAtomValue } from "jotai";
  4→import { MatrixAtoms } from "modules/matrix-client/jotai";
  5→import { MatrixService } from "modules/matrix-client/services";
  6→import { type FC, useEffect, useState } from "react";
  7→import { ActivityIndicator, Image } from "react-native";
  8→import Toast from "react-native-toast-message";
  9→import { Button, GoBackHeader, ScreenLayout } from "shared/components";
 10→import { useNavigateToCorrectScreenHelper } from "shared/hooks";
 11→import { Colors, TextSize } from "shared/styles";
