 13→
 14→export const VerifyWithDevice: FC<
 15→  NativeStackScreenProps<Routes, "verifyWithDevice">
 16→> = ({ navigation }) => {
 17→  const verificationStatus = useAtomValue(MatrixAtoms.verificationStatus);
 18→  const [deviceId, setDeviceId] = useState<string | null>(null);
 19→  const [requestSent, setRequestSent] = useState(false);
 20→  const [error, setError] = useState<string | null>(null);
 21→  const navigateToCorrectScreen = useNavigateToCorrectScreenHelper();
 22→
 23→  const isWaiting =
 24→    requestSent &&
 25→    verificationStatus !== "emojis" &&
 26→    verificationStatus !== "success" &&
 27→    verificationStatus !== "failed" &&
 28→    verificationStatus !== "cancelled";
 29→  const isEmojis = verificationStatus === "emojis";
 30→
 31→  useEffect(() => {
 32→    setDeviceId(MatrixService.getDeviceId());
 33→  }, []);
 34→
 35→  // Initiate device verification on mount
 36→  useEffect(() => {
 37→    const requestVerification = async () => {
 38→      try {
 39→        await MatrixService.requestDeviceVerification();
 40→        setRequestSent(true);
 41→      } catch (err) {
 42→        console.error("Failed to request device verification:", err);
 43→        setError("Failed to send verification request. Please try again.");
 44→      }
 45→    };
 46→    requestVerification();
 47→  }, []);
 48→
 49→  // Handle terminal states
 50→  useEffect(() => {
 51→    if (verificationStatus === "success") {
 52→      Toast.show({
 53→        text1: "Device verified successfully!",
 54→        text2: "You can now access your encrypted messages",
 55→        type: "success",
 56→      });
 57→      navigateToCorrectScreen();
 58→    } else if (verificationStatus === "failed") {
 59→      setError("Verification failed. Please try again.");
 60→      setRequestSent(false);
 61→    } else if (verificationStatus === "cancelled") {
 62→      setError("Verification was cancelled. Please try again.");
 63→      setRequestSent(false);
 64→    }
 65→  }, [verificationStatus]);
 66→
 67→  const handleRetry = async () => {
 68→    setError(null);
 69→    try {
 70→      await MatrixService.requestDeviceVerification();
 71→      setRequestSent(true);
 72→    } catch (err) {
 73→      console.error("Failed to request device verification:", err);
 74→      setError("Failed to send verification request. Please try again.");
 75→    }
 76→  };
 77→
 78→  if (isEmojis) {
 79→    return (
 80→      <ScreenLayout>
 81→        <GoBackHeader />
 82→        <EmojiVerification />
 83→      </ScreenLayout>
 84→    );
 85→  }
 86→
 87→  return (
 88→    <ScreenLayout>
 89→      <GoBackHeader />
 90→      <Block flex={1} justify="space-between">
 91→        <Block flex={1} justify="center" align="center" gap={32}>
 92→          <Block gap={12}>
 93→            <Text
 94→              size={TextSize.large}
 95→              textAlign="center"
 96→              font="InstrumentSans-Medium"
 97→            >
 98→              Verify with another device
 99→            </Text>
100→            <Text
101→              textAlign="center"
102→              font="InstrumentSans-Regular"
103→              color={Colors.white50}
104→            >
105→              A verification request has been sent to your other devices. Accept
106→              it on a verified device to compare emojis.
107→            </Text>
108→          </Block>
109→
110→          {deviceId && (
111→            <Block
112→              border={{ borderRadius: 12 }}
113→              background={Colors.white5}
114→              paddings={[16, 16]}
115→              width="100%"
116→            >
117→              <Text color={Colors.white50} size={TextSize.small}>
118→                This device ID: {deviceId}
119→              </Text>
120→            </Block>
121→          )}
122→
123→          {isWaiting && (
124→            <Block flexDirection="row" align="center" gap={12}>
125→              <ActivityIndicator color={Colors.primary} />
126→              <Text color={Colors.white50}>
127→                Waiting for the other device...
128→              </Text>
129→            </Block>
130→          )}
131→
132→          {error && (
133→            <Block
134→              border={{ borderRadius: 12 }}
135→              background={Colors.white5}
136→              paddings={[16, 16]}
137→              gap={12}
138→              width="100%"
139→            >
140→              <Text color="red" textAlign="center">
141→                {error}
142→              </Text>
143→              <Button.Primary onPress={handleRetry}>Try Again</Button.Primary>
144→            </Block>
145→          )}
146→
147→          <Block
148→            border={{ borderRadius: 12 }}
149→            background={Colors.blackMinus3}
150→            paddings={[12, 16]}
151→            flexDirection="row"
152→            align="center"
153→            gap={12}
154→          >
155→            <Image
156→              source={require("assets/icons/info.png")}
157→              tintColor={Colors.primary}
158→              width={20}
159→              height={20}
160→            />
161→            <Text color={Colors.white80} size={TextSize.small} flex={1}>
162→              Don't have access to another verified device? Go back and use your
163→              recovery key instead.
164→            </Text>
165→          </Block>
166→        </Block>
167→
168→        <Button.Outline onPress={() => navigation.goBack()}>
169→          Go Back
170→        </Button.Outline>
171→      </Block>
172→    </ScreenLayout>
173→  );
174→};
